/** Languages supported by Doulisha (specification section 8). */
declare const locales: readonly ["ar", "fr", "en"];
type Locale = (typeof locales)[number];

/**
 * @doulisha/i18n: locales, messages (ar, fr, en) and formatters (TND, Africa/Tunis dates).
 * Framework-free so the future mobile app can reuse it (ADR 0006).
 */

/** Text written in the three interface languages (categories, templates). */
interface LocalizedText {
    ar: string;
    fr: string;
    en: string;
}

type CancellationPolicy = 'flexible' | 'moderate' | 'strict';
type RegistrationType = 'free_rsvp' | 'paid' | 'deposit' | 'pay_at_door';
/** Modules a template switches on (spec 6.2). */
type TemplateModule = 'tickets' | 'payments' | 'attendees' | 'checkin' | 'waitlist' | 'itinerary' | 'meeting_points' | 'invitations' | 'rsvp' | 'gift_pool' | 'providers' | 'slots';
interface FieldBase {
    /** Key inside `events.details`. */
    key: string;
    label: LocalizedText;
    help?: LocalizedText;
    required?: boolean;
}
type TemplateField = (FieldBase & {
    type: 'number';
    min?: number;
    max?: number;
    step?: number;
    unit?: string;
}) | (FieldBase & {
    type: 'text';
    maxLength?: number;
    multiline?: boolean;
}) | (FieldBase & {
    type: 'select';
    options: {
        value: string;
        label: LocalizedText;
    }[];
    multiple?: boolean;
}) | (FieldBase & {
    type: 'boolean';
})
/** A media id pointing to an uploaded GPX track. */
 | (FieldBase & {
    type: 'gpx';
});
/** EVT-05 brief as stored on an event, in the event's language. */
interface EventBrief {
    whatToBring?: string[];
    dressCode?: string;
    rules?: string;
    safety?: string;
}
/** Default brief offered by the wizard, in the three interface languages. */
interface LocalizedBrief {
    whatToBring?: LocalizedText[];
    dressCode?: LocalizedText;
    rules?: LocalizedText;
    safety?: LocalizedText;
}
/** JSON stored in `templates.definition`. Admins can edit it (EVT-09). */
interface TemplateDefinitionData {
    fields: TemplateField[];
    defaultBrief: LocalizedBrief;
    cancellationPolicy: CancellationPolicy;
    registrationTypes: RegistrationType[];
    modules: TemplateModule[];
    /** Keys of `fields` exposed as search filters (DSC-01). */
    searchFilters: string[];
    /** Visual style for generated share images (SHR-02). */
    shareStyle: {
        accent: string;
        layout: 'photo' | 'poster' | 'invitation';
    };
    defaultVisibility: 'public' | 'unlisted' | 'private';
}

