/** Providers from BUILD_PROMPT section 3. Konnect and Flouci arrive in Phase 6. */
type PaymentProviderId = 'mock' | 'manual' | 'konnect' | 'flouci';
/** PAY-02 methods. Online: card, e-Dinar. Offline: D17, cash, bank transfer (with proof). */
type PaymentMethod = 'card' | 'e_dinar' | 'd17' | 'cash' | 'bank_transfer';
interface CreatePaymentInput {
    /** Our payment row id; the provider echoes it back in webhooks. */
    paymentId: string;
    orderReference: string;
    amountMillimes: number;
    method: PaymentMethod;
    /** Where the buyer returns after paying online. */
    returnUrl: string;
    locale: 'ar' | 'fr' | 'en';
}
type CreatePaymentResult = 
/** Online: send the buyer to the gateway. */
{
    kind: 'redirect';
    url: string;
    providerRef: string;
}
/** Offline: the organizer confirms later (cash, transfer, D17 with proof). */
 | {
    kind: 'pending_manual';
};
/** A verified event from a provider webhook. */
interface PaymentEvent {
    paymentId: string;
    providerRef: string;
    status: 'succeeded' | 'failed';
    amountMillimes: number;
    /** Unique per event, so a replayed webhook is processed once. */
    eventId: string;
}
interface RefundInput {
    paymentId: string;
    providerRef: string | null;
    amountMillimes: number;
}
interface PaymentProvider {
    readonly id: PaymentProviderId;
    /** Methods this provider handles. */
    readonly methods: readonly PaymentMethod[];
    createPayment(input: CreatePaymentInput): Promise<CreatePaymentResult>;
    /**
     * Verifies a webhook's signature and parses it. Throws on an invalid
     * signature; never trust a webhook body before this returns.
     */
    parseWebhook(body: string, headers: Headers): Promise<PaymentEvent>;
    /** Sends money back. Manual refunds are done by the organizer outside Doulisha. */
    refund(input: RefundInput): Promise<{
        providerRef: string | null;
    }>;
}

interface UploadTicket {
    method: 'PUT';
    /** Where the browser sends the file. */
    url: string;
    headers: Record<string, string>;
    key: string;
}
interface StorageProvider {
    readonly id: 'local' | 'r2';
    createUpload(input: {
        key: string;
        bucket: 'public' | 'private';
        contentType: string;
        maxBytes: number;
    }): Promise<UploadTicket>;
    /** URL of a public object. Private objects are only served through permission checks. */
    publicUrl(key: string): string;
}

/**
 * Infrastructure the services need, injected by the app so the API package
 * never reads environment variables (and tests can pass fakes).
 */
interface ServiceDeps {
    /** Runs `fn` in a database transaction (WebSocket Pool). */
    transaction: <T>(fn: (tx: Tx) => Promise<T>) => Promise<T>;
    payments: Partial<Record<PaymentProviderId, PaymentProvider>>;
    storage: StorageProvider;
    /** Absolute base URL of the web app, e.g. https://doulisha.tn. */
    appUrl: string;
    /**
     * Sends a message to a buyer (SMS, or email when there is no phone). The app
     * renders the text in the buyer's language. Optional: tests and scripts skip it.
     */
    notify?: (notice: BuyerNotice) => Promise<void>;
}
/** What happened to a booking, for the message sent to its buyer (ADR 0018). */
interface BuyerNotice {
    kind: 'payment_confirmed' | 'receipt_rejected' | 'reservation_cancelled';
    locale: Locale;
    reference: string;
    eventTitle: string;
    to: {
        phone: string | null;
        email: string | null;
    };
    amountMillimes?: number;
    /** For rejected receipts: wrong_amount, unreadable, not_received or other. */
    reason?: string | null;
    note?: string | null;
}

interface Actor {
    userId: string;
    roles: readonly UserRole[];
    isAnonymous: boolean;
}

/**
 * Named explicitly so the router declarations refer to it instead of
 * repeating the whole Better Auth and Drizzle types (ADR 0024).
 */
interface Context {
    db: HttpDb;
    auth: Auth;
    session: AuthSession | null;
    actor: Actor | null;
    locale: Locale;
    deps: ServiceDeps;
    headers: Headers;
}

/** What an event needs before it can be published; each key maps to a message. */
type PublishProblem = 'title' | 'startsAt' | 'endsAt' | 'city' | 'tickets' | 'paidTickets' | 'organizer' | 'capacity' | `details.${string}`;

/** Social providers a member can connect to their account (ACC-01, ADR 0019). */
declare const SOCIAL_PROVIDERS: readonly ["google", "facebook", "apple"];
type SocialProvider = (typeof SOCIAL_PROVIDERS)[number];
/** Every way a member can get into their account. */
interface SignInMethods {
    /** Verified phone number: sign-in by SMS code. */
    phone: string | null;
    /** Real email address (not a placeholder): sign-in by email code. */
    email: string | null;
    hasPassword: boolean;
    providers: {
        providerId: SocialProvider;
        linkedAt: Date;
    }[];
}

type PaymentChoice = 'online' | 'd17' | 'bank_transfer' | 'cash';
interface BookingResult {
    reference: string;
    status: 'confirmed' | 'awaiting_payment' | 'waitlisted';
    /** Online payment: where to send the buyer. */
    redirectUrl?: string;
}

/** PRT-01 payment status of a person, from their order. */
type AttendeePayment = 'paid' | 'deposit' | 'pending' | 'refunded' | 'cancelled' | 'waitlisted';
type CheckInResult = {
    status: 'checked_in';
    fullName: string;
    ticketName: string | null;
    payment: AttendeePayment;
} | {
    status: 'payment_due';
    fullName: string;
    ticketName: string | null;
    dueMillimes: number;
} | {
    status: 'already';
    fullName: string;
    checkedInAt: Date;
} | {
    status: 'invalid';
};

